149	    /**
150	     * The owner's age band, derived at response time from {@link #birthDate} against
151	     * {@link #registrationDate}: {@code MINOR} when under 18 years old, {@code ADULT} when 18 to 64,
152	     * and {@code SENIOR} when 65 or over. {@code null} when the owner has no birth date (or no
153	     * registration date to compute against). Not persisted.
154	     */
155	    public String getAgeBand() {
156	        if (this.birthDate == null || this.registrationDate == null) {
157	            return null;
158	        }
159	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
160	        if (age < 18) {
161	            return "MINOR";
162	        }
163	        if (age < 65) {
164	            return "ADULT";
