201	    /**
202	     * Whether this owner, when created, was a possible (soft) duplicate of an earlier owner, keyed
203	     * off the shared {@link #getHouseholdId() householdId} (same lastName and postcode). A declared
204	     * household member (created with {@code sharesHousehold} true) is never flagged; any other owner
205	     * joining an existing household is rejected 409 instead. {@code false} when no such earlier owner
206	     * existed. Assigned at creation.
207	     */
208	    public Boolean getPossibleDuplicate() {
209	        return this.possibleDuplicate;
210	    }
211	
212	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
213	        this.possibleDuplicate = possibleDuplicate;
214	    }
215	
216	    /**
217	     * The id of the earlier owner this owner is a possible duplicate of (the earliest such match),
218	     * or {@code null} when {@link #getPossibleDuplicate()} is false. Assigned at creation.
219	     */
220	    public Integer getPossibleDuplicateOf() {
221	        return this.possibleDuplicateOf;
222	    }
223	
224	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
225	        this.possibleDuplicateOf = possibleDuplicateOf;
226	    }
227	
228	    /**
229	     * Whether more than 80 owners had already been created on this owner's registration day,
230	     * derived at response time and not persisted. {@code true} triggers a bulk-signup warning
231	     * in the response.
232	     */
233	    public Boolean getBulkSignupWarning() {
234	        return this.bulkSignupWarning;
235	    }
236	
237	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
238	        this.bulkSignupWarning = bulkSignupWarning;
239	    }
