241	    /**
242	     * The number of owners in this owner's household (owners sharing the same
243	     * {@link #householdId}), derived at response time and not persisted.
244	     */
245	    public Integer getHouseholdSize() {
246	        return this.householdSize;
247	    }
248	
249	    public void setHouseholdSize(Integer householdSize) {
250	        this.householdSize = householdSize;
251	    }
252	
253	    /**
254	     * The owner's numeric membership level, assigned at creation. Starts at {@code 1}, plus 1 when
255	     * an email is present, plus 1 when {@link #namesakeCount} is 0, capped at {@code 3} (level 4 is
256	     * reserved for tenure).
257	     */
258	    public Integer getMembershipLevel() {
259	        int level = 1;
260	        if (this.email != null && !this.email.isEmpty()) {
261	            level++;
262	        }
263	        if (this.namesakeCount != null && this.namesakeCount == 0) {
264	            level++;
265	        }
266	        return Math.min(level, 3);
267	    }
268	
269	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
270	    private static final Map<String, String> CITY_REGION = Map.of(
271	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
272	
273	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
274	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
275	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
276	
277	    /**
278	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
279	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
280	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
281	     * for {@code null} before range-checking the postcode.
282	     */
283	    public static String regionOf(String city) {
284	        return CITY_REGION.get(city);
285	    }
286	
287	    /**
288	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
289	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
290	     * absent, not a 4-digit number, or in no known range.
291	     */
292	    public static String regionOfPostcode(String postcode) {
293	        if (postcode == null || postcode.isEmpty()) {
294	            return null;
295	        }
296	        int value;
297	        try {
298	            value = Integer.parseInt(postcode);
299	        } catch (NumberFormatException ex) {
300	            return null;
301	        }
302	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
303	            int[] range = entry.getValue();
304	            if (value >= range[0] && value <= range[1]) {
305	                return entry.getKey();
306	            }
307	        }
308	        return null;
309	    }
310	
311	    /**
312	     * The owner's region, derived at response time from the {@code REGION} prefix of the
313	     * {@link #customerCode} (the segment before the first {@code '-'}). Because the customer code is
314	     * assigned as {@code <REGION>-<HASH8>} with REGION taken from the postcode, the locality follows
315	     * the same region-and-hash identity as the customer code. {@code UNKNOWN} when the owner has no
316	     * customer code.
317	     */
318	    public String getLocality() {
319	        if (this.customerCode == null) {
320	            return "UNKNOWN";
321	        }
322	        int dash = this.customerCode.indexOf('-');
323	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
324	    }
325	
326	    /**
327	     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
328	     * email is present, otherwise {@code PHONE}. Not persisted.
329	     */
330	    public String getContactPreference() {
331	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
332	    }
333	
334	    /**
335	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
336	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
337	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
338	     * digit from the right, subtracting 9 from any result over 9, and taking
339	     * {@code (10 - sum % 10) % 10}. Not persisted.
340	     */
341	    public Integer getCheckDigit() {
342	        if (this.customerCode == null) {
343	            return null;
344	        }
345	        int sum = 0;
346	        boolean dbl = true;
347	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
348	            char c = this.customerCode.charAt(i);
349	            if (c < '0' || c > '9') {
350	                continue;
351	            }
352	            int d = c - '0';
353	            if (dbl) {
354	                d *= 2;
355	                if (d > 9) {
356	                    d -= 9;
357	                }
358	            }
359	            sum += d;
360	            dbl = !dbl;
361	        }
362	        return (10 - (sum % 10)) % 10;
363	    }
364	
365	    /**
366	     * The single source of truth for an owner's identity: the derived key
367	     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
368	     * canonical E.164 form and the email lower-cased, so this key composes their canonical values;
369	     * an absent email or householdId contributes an empty segment. Two owners are duplicates exactly
370	     * when their whole identity keys are equal — differing in any one segment (for example two
371	     * members of the same household with different telephones) yields different keys. Derived at
372	     * response time and used by the create pipeline's single duplicate check; not persisted.
373	     */
374	    public String getIdentityKey() {
375	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
376	    }
377	
378	    private static String keyPart(String value) {
379	        return value == null ? "" : value;
380	    }
381	
382	    protected Set<Pet> getPetsInternal() {
383	        if (this.pets == null) {
384	            this.pets = new HashSet<>();
385	        }
386	        return this.pets;
387	    }
388	
389	    protected void setPetsInternal(Set<Pet> pets) {
390	        this.pets = pets;
391	    }
392	
393	    public List<Pet> getPets() {
394	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
395	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
396	        return Collections.unmodifiableList(sortedPets);
397	    }
398	
399	    public void setPets(List<Pet> pets) {
400	        this.pets = new HashSet<>(pets);
401	    }
402	
403	    public void addPet(Pet pet) {
404	        getPetsInternal().add(pet);
405	        pet.setOwner(this);
406	    }
407	
408	    /**
409	     * Return the Pet with the given name, or null if none found for this Owner.
410	     *
411	     * @param name to test
412	     * @return true if pet name is already in use
413	     */
414	    public Pet getPet(String name) {
415	        return getPet(name, false);
416	    }
417	
418	    /**
419	     * Return the Pet with the given name, or null if none found for this Owner.
420	     *
421	     * @param name to test
422	     * @return true if pet name is already in use
423	     */
424	    public Pet getPet(String name, boolean ignoreNew) {
425	        name = name.toLowerCase();
426	        for (Pet pet : getPetsInternal()) {
427	            if (!ignoreNew || !pet.isNew()) {
428	                String compName = pet.getName();
429	                compName = compName.toLowerCase();
430	                if (compName.equals(name)) {
431	                    return pet;
432	                }
433	            }
434	        }
435	        return null;
436	    }
437	
438	    public Pet getPet(Integer petId) {
439	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
440	    }
441	
442	    @Override
443	    public String toString() {
444	        return new ToStringCreator(this)
445	
446	            .append("id", this.getId())
447	            .append("new", this.isNew())
448	            .append("lastName", this.getLastName())
449	            .append("firstName", this.getFirstName())
450	            .append("address", this.address)
451	            .append("city", this.city)
452	            .append("telephone", this.telephone)
453	            .append("email", this.email)
454	            .toString();
455	    }
456	}
